((root,factory)=>{const api=factory(typeof module==='object'&&module.exports?require('./persamaan-linear-core.js'):root.LinearLesson);if(typeof module==='object'&&module.exports)module.exports=api;else root.ReadinessLesson=api;})(typeof window==='undefined'?globalThis:window,num=>{
'use strict';
const groups=[{id:'numbers',title:'Bilangan dan operasi'},{id:'algebra',title:'Bahasa aljabar'},{id:'equations',title:'Persamaan dan pertidaksamaan'},{id:'coordinates',title:'Koordinat dan hubungan'},{id:'functions',title:'Fungsi'},{id:'families',title:'Keluarga fungsi'},{id:'explog',title:'Eksponensial dan logaritma'},{id:'trig',title:'Trigonometri'},{id:'bridge',title:'Jembatan menuju kalkulus'}];
const questions=[
{id:'q01',group:'numbers',kind:'number',tex:String.raw`\frac34+\frac16`,prompt:'Berapa hasil penjumlahan ini?',n:11,d:12,why:'Samakan penyebut menjadi dua belas. Sembilan per dua belas ditambah dua per dua belas menghasilkan sebelas per dua belas.',review:[['operasi-pecahan.html','Menjumlahkan dan Mengurangkan Pecahan']]},
{id:'q02',group:'numbers',kind:'number',tex:String.raw`-3^2`,prompt:'Berapa nilainya sesuai urutan operasi?',n:-9,d:1,why:'Pangkat dikerjakan sebelum tanda negatif di luar. Bentuk ini adalah negatif dari sembilan, berbeda dengan kuadrat dari negatif tiga.',review:[['urutan-operasi.html','Urutan Operasi dan Tanda Kurung'],['pangkat-akar.html','Pangkat dan Akar']]},
{id:'q03',group:'algebra',kind:'choice',tex:String.raw`x^2-9`,prompt:'Manakah faktorisasi yang benar?',options:[{tex:String.raw`(x-3)^2`,label:'x dikurangi tiga, seluruhnya dikuadratkan'},{tex:String.raw`(x-3)(x+3)`,label:'x dikurangi tiga dikali x ditambah tiga'},{tex:String.raw`x(x-9)`,label:'x dikali x dikurangi sembilan'}],answer:1,why:'Selisih dua kuadrat adalah hasil kali selisih dan jumlah kedua bilangan. Mengalikan kembali kedua faktor menghasilkan x kuadrat dikurangi sembilan.',review:[['faktorisasi.html','Faktorisasi']]},
{id:'q04',group:'algebra',kind:'choice',tex:String.raw`\frac{x^2-9}{x-3}`,prompt:'Manakah penyederhanaan beserta syarat yang benar?',options:[{tex:String.raw`x+3,\quad x\ne3`,label:'x ditambah tiga, dengan x bukan tiga'},{tex:String.raw`x+3\text{ untuk semua }x\in\mathbb R`,label:'x ditambah tiga untuk semua bilangan real'},{tex:String.raw`x-3,\quad x\ne3`,label:'x dikurangi tiga, dengan x bukan tiga'}],answer:0,why:'Faktorkan pembilang lalu batalkan faktor x dikurangi tiga. Fungsi awal tetap mempunyai syarat pembagi bukan nol, sehingga x bukan tiga.',review:[['faktorisasi.html','Faktorisasi'],['fungsi-rasional.html','Fungsi Rasional']]},
{id:'q05',group:'equations',kind:'number',tex:String.raw`3(x-2)=9`,prompt:'Berapa nilai x yang memenuhi?',n:5,d:1,why:'Bagi kedua sisi dengan tiga, sehingga x dikurangi dua sama dengan tiga. Tambahkan dua pada kedua sisi: x sama dengan lima.',review:[['persamaan-linear.html','Persamaan Linear Satu Variabel']]},
{id:'q06',group:'equations',kind:'choice',tex:String.raw`-2x<6`,prompt:'Manakah seluruh himpunan solusinya?',options:[{tex:String.raw`x<-3`,label:'x lebih kecil dari negatif tiga'},{tex:String.raw`x>3`,label:'x lebih besar dari tiga'},{tex:String.raw`x>-3`,label:'x lebih besar dari negatif tiga'}],answer:2,why:'Membagi kedua sisi dengan negatif dua membalik arah pertidaksamaan. Hasilnya x lebih besar dari negatif tiga.',review:[['pertidaksamaan-linear.html','Pertidaksamaan Linear Satu Variabel']]},
{id:'q07',group:'coordinates',kind:'number',tex:String.raw`P=(-1,2),\quad Q=(3,10)`,prompt:'Berapa kemiringan garis melalui kedua titik?',n:2,d:1,why:'Perubahan tegak delapan dibagi perubahan mendatar empat menghasilkan dua. Urutan pengurangan harus sama pada pembilang dan penyebut.',review:[['garis.html','Kemiringan dan Persamaan Garis']]},
{id:'q08',group:'coordinates',kind:'choice',tex:String.raw`(2,-3)`,prompt:'Di kuadran mana titik ini berada?',options:[{text:'Kuadran I.'},{text:'Kuadran IV.'},{text:'Kuadran II.'}],answer:1,why:'Koordinat mendatar positif berarti kanan, koordinat tegak negatif berarti bawah. Posisi kanan bawah adalah kuadran IV.',review:[['koordinat.html','Koordinat Kartesius']]},
{id:'q09',group:'functions',kind:'number',tex:String.raw`\begin{gathered}f(x)=2x+1,\quad g(x)=x^2\\f(g(-2))=?\end{gathered}`,prompt:'Berapa nilai komposisi tersebut?',n:9,d:1,why:'Kerjakan fungsi bagian dalam: g negatif dua adalah empat. Kemudian f empat adalah dua kali empat ditambah satu, yaitu sembilan.',review:[['komposisi-fungsi.html','Operasi dan Komposisi Fungsi']]},
{id:'q10',group:'functions',kind:'choice',tex:String.raw`F(x)=\frac{\sqrt{x-1}}{x-3}`,prompt:'Manakah domain real fungsi ini?',options:[{tex:String.raw`x\ge1,\quad x\ne3`,label:'x paling kecil satu dan bukan tiga'},{tex:String.raw`x\ge1`,label:'Semua x paling kecil satu'},{tex:String.raw`x\ne3`,label:'Semua x bukan tiga'}],answer:0,why:'Akar real memerlukan x dikurangi satu tidak negatif. Pembagi juga harus bukan nol. Gabungannya adalah x paling kecil satu dan x bukan tiga.',review:[['domain-range.html','Domain dan Range']]},
{id:'q11',group:'families',kind:'choice',tex:String.raw`y=(x-2)^2+1`,prompt:'Di mana titik puncak parabola ini?',options:[{tex:String.raw`(-2,1)`,label:'Negatif dua, satu'},{tex:String.raw`(2,-1)`,label:'Dua, negatif satu'},{tex:String.raw`(2,1)`,label:'Dua, satu'}],answer:2,why:'Dari kuadrat dasar, grafik bergeser dua ke kanan dan satu ke atas. Titik puncaknya dua, satu.',review:[['transformasi-fungsi.html','Transformasi Grafik Fungsi'],['fungsi-kuadrat.html','Fungsi Kuadrat']]},
{id:'q12',group:'families',kind:'number',tex:String.raw`f(x)=\frac1{x-2}`,prompt:'Berapa nilai fungsi pada masukan satu?',n:-1,d:1,why:'Masukkan satu: penyebut satu dikurangi dua adalah negatif satu. Satu dibagi negatif satu adalah negatif satu.',review:[['fungsi-rasional.html','Fungsi Rasional']]},
{id:'q13',group:'explog',kind:'number',tex:String.raw`2^{x+1}=8`,prompt:'Berapa nilai x yang memenuhi?',n:2,d:1,why:'Delapan sama dengan dua pangkat tiga. Maka x ditambah satu sama dengan tiga, sehingga x sama dengan dua.',review:[['persamaan-eksponen-log.html','Persamaan Eksponensial dan Logaritma']]},
{id:'q14',group:'explog',kind:'number',tex:String.raw`\log_2(1/8)`,prompt:'Berapa nilainya?',n:-3,d:1,why:'Logaritma menanyakan pangkat. Dua pangkat negatif tiga sama dengan seperdelapan, sehingga nilainya negatif tiga.',review:[['fungsi-logaritma.html','Logaritma']]},
{id:'q15',group:'trig',kind:'number',tex:String.raw`\sin(\pi/6)`,prompt:'Berapa nilai sinus sudut ini?',n:1,d:2,why:'Pi per enam adalah tiga puluh derajat. Koordinat tegak titik pada lingkaran satuannya setengah.',review:[['lingkaran-satuan.html','Lingkaran Satuan, Sinus, dan Kosinus']]},
{id:'q16',group:'trig',kind:'choice',tex:String.raw`\arcsin(\sin(5\pi/6))`,prompt:'Manakah sudut utama hasil komposisi ini?',options:[{tex:String.raw`5\pi/6`,label:'Lima pi per enam'},{tex:String.raw`\pi/6`,label:'Pi per enam'},{tex:String.raw`-\pi/6`,label:'Negatif pi per enam'}],answer:1,why:'Sinus lima pi per enam adalah setengah. Arcsin memilih pi per enam karena hasilnya harus berada antara negatif setengah pi dan setengah pi.',review:[['trigonometri-invers.html','Fungsi Trigonometri Invers']]},
{id:'q17',group:'bridge',kind:'number',tex:String.raw`f(x)=x^2,\quad a=1,\quad b=3`,prompt:'Berapa laju perubahan rata-rata dari masukan satu ke tiga?',n:4,d:1,why:'Sembilan dikurangi satu dibagi tiga dikurangi satu menghasilkan empat. Ini kemiringan sekan, berbeda dari rata-rata dua nilai keluaran.',review:[['laju-perubahan.html','Laju Perubahan Rata-Rata']]},
{id:'q18',group:'bridge',kind:'choice',tex:String.raw`\lim_{x\to1}f(x)=2,\quad f(1)=4`,prompt:'Apa kesimpulan tentang kekontinuan di satu?',options:[{text:'Tidak kontinu karena nilai fungsi dan limit berbeda.'},{text:'Kontinu karena limit ada.'},{text:'Kontinu karena nilai fungsi di titik ada.'}],answer:0,why:'Kekontinuan memerlukan nilai titik terdefinisi, limit ada, dan keduanya sama. Pada data ini syarat terakhir tidak terpenuhi.',review:[['gagasan-limit.html','Memahami Gagasan Limit'],['kekontinuan.html','Kekontinuan Fungsi']]}
];
function cleanAnswers(source){const out={};if(!source||typeof source!=='object'||Array.isArray(source))return out;for(const q of questions)if(typeof source[q.id]==='string'){const s=source[q.id].trim().slice(0,80);if(s)out[q.id]=s;}return out;}
function check(q,raw){const s=typeof raw==='string'?raw.trim():'';if(!s)return {status:'pending'};if(q.kind==='number'){const value=num.parseAnswer(s);return {status:!value?'invalid':num.equalAnswer(value,num.rational(q.n,q.d))?'correct':'incorrect'};}if(!/^\d+$/.test(s)||Number(s)>=q.options.length)return {status:'invalid'};return {status:Number(s)===q.answer?'correct':'incorrect'};}
function evaluate(source){const answers=cleanAnswers(source),items={},totals={correct:0,incorrect:0,invalid:0,pending:0};for(const q of questions){items[q.id]=check(q,answers[q.id]);totals[items[q.id].status]++;}const topics=groups.map(group=>{const counts={correct:0,incorrect:0,invalid:0,pending:0},review=[];for(const q of questions.filter(q=>q.group===group.id)){const status=items[q.id].status;counts[status]++;if(status==='incorrect')for(const link of q.review)if(!review.some(r=>r[0]===link[0]))review.push(link);}return {...group,...counts,total:2,review};});return {...totals,answered:questions.length-totals.pending,items,topics};}
function captureFirst(first,source){const out=cleanAnswers(first),answers=cleanAnswers(source);for(const q of questions){if(out[q.id]&&!['correct','incorrect'].includes(check(q,out[q.id]).status))delete out[q.id];const status=check(q,answers[q.id]).status;if(!out[q.id]&&(status==='correct'||status==='incorrect'))out[q.id]=answers[q.id];}return out;}
return {groups,questions,cleanAnswers,check,evaluate,captureFirst};
});